const ExplainerDiagrams=(()=>{const PADDING=20;const MAX_SCALE=4;function viewportSize(width,content){const scale=Math.min(1,Math.max(1,width-PADDING*2)/content.width);return{width,height:Math.max(180,Math.min(480,content.height*scale+PADDING*2))}}function constrainView(viewport,content,view){const offset=(available,size,value)=>size<=available-PADDING*2?(available-size)/2:Math.min(PADDING,Math.max(available-PADDING-size,value));return{scale:view.scale,x:offset(viewport.width,content.width*view.scale,view.x),y:offset(viewport.height,content.height*view.scale,view.y)}}function fitView(viewport,content){const scale=Math.min(1,Math.max(1,viewport.width-PADDING*2)/content.width,Math.max(1,viewport.height-PADDING*2)/content.height);return constrainView(viewport,content,{scale,x:0,y:0})}function gestureFrame(points){if(!points.length)return null;const[first,second]=points;if(!second)return{...first,distance:1};return{x:(first.x+second.x)/2,y:(first.y+second.y)/2,distance:Math.max(1,Math.hypot(second.x-first.x,second.y-first.y))}}function gestureView(viewport,content,view,from,to){const minimum=fitView(viewport,content).scale;const scale=Math.min(MAX_SCALE,Math.max(minimum,view.scale*to.distance/from.distance));const ratio=scale/view.scale;return constrainView(viewport,content,{scale,x:to.x-(from.x-view.x)*ratio,y:to.y-(from.y-view.y)*ratio})}function zoomView(viewport,content,view,factor,anchor){return gestureView(viewport,content,view,{...anchor,distance:1},{...anchor,distance:factor})}function bind(viewport){const svg=viewport.querySelector(".graph-svg,.sequence-svg");const toolbar=viewport.parentElement.querySelector(":scope > .diagram-header > .diagram-tools");if(!svg||!toolbar?.classList.contains("diagram-tools")||typeof ResizeObserver==="undefined")return;const box=svg.viewBox.baseVal;const width=parseFloat(getComputedStyle(svg).getPropertyValue("--diagram-min-width"));if(!(width>0&&box.width>0&&box.height>0))return;const content={width,height:width*box.height/box.width};const output=toolbar.querySelector("output");const zoomOut=toolbar.querySelector('[data-diagram-action="out"]');const zoomIn=toolbar.querySelector('[data-diagram-action="in"]');let panel=null;let view=null;let fitted=true;let drag=null;const pointers=new Map;function paint(){svg.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;output.value=`${Math.round(view.scale*100)}%`;zoomOut.disabled=view.scale<=fitView(panel,content).scale+1e-6;zoomIn.disabled=view.scale>=MAX_SCALE-1e-6}function refresh(){const width=viewport.clientWidth;if(!width||panel&&panel.width===width)return;clearGesture();const previous=panel;panel=viewportSize(width,content);viewport.style.height=`${panel.height}px`;if(fitted||!view)view=fitView(panel,content);else{const scale=Math.max(fitView(panel,content).scale,view.scale);view=constrainView(panel,content,{scale,x:panel.width/2-(previous.width/2-view.x)*scale/view.scale,y:panel.height/2-(previous.height/2-view.y)*scale/view.scale})}viewport.classList.add("diagram-panzoom");viewport.tabIndex=0;viewport.setAttribute("role","group");viewport.setAttribute("aria-label",`${svg.getAttribute("aria-label")} viewer`);viewport.setAttribute("aria-describedby",viewport.dataset.diagramHelp);toolbar.hidden=false;toolbar.parentElement.hidden=false;paint()}function fit(){if(!panel)return;clearGesture();fitted=true;view=fitView(panel,content);paint()}function zoom(factor,anchor={x:panel.width/2,y:panel.height/2}){clearGesture();view=zoomView(panel,content,view,factor,anchor);fitted=view.scale<=fitView(panel,content).scale+1e-6;paint()}function rebaseGesture(){const frame=gestureFrame([...pointers.values()]);drag=frame?{view,frame}:null;viewport.classList.toggle("is-panning",Boolean(drag))}function clearGesture(){const captured=[...pointers.keys()];pointers.clear();drag=null;viewport.classList.remove("is-panning");for(const id of captured){if(viewport.hasPointerCapture(id))viewport.releasePointerCapture(id)}}function endPointer(event){if(!pointers.has(event.pointerId))return;pointers.delete(event.pointerId);rebaseGesture();if(viewport.hasPointerCapture(event.pointerId))viewport.releasePointerCapture(event.pointerId)}function pointerPosition(event){const bounds=viewport.getBoundingClientRect();return{x:event.clientX-bounds.left,y:event.clientY-bounds.top}}zoomOut.addEventListener("click",()=>zoom(1/1.25));zoomIn.addEventListener("click",()=>zoom(1.25));toolbar.querySelector('[data-diagram-action="fit"]').addEventListener("click",fit);viewport.addEventListener("wheel",event=>{if(!(event.ctrlKey||event.metaKey)||!view||!event.deltaY)return;event.preventDefault();const bounds=viewport.getBoundingClientRect();const delta=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?panel.height:1);zoom(Math.exp(-Math.max(-200,Math.min(200,delta))*.002),{x:event.clientX-bounds.left,y:event.clientY-bounds.top})},{passive:false});viewport.addEventListener("pointerdown",event=>{if(!view||event.button!==0||event.pointerType!=="touch"&&!event.isPrimary)return;event.preventDefault();viewport.focus({preventScroll:true});pointers.set(event.pointerId,pointerPosition(event));viewport.setPointerCapture(event.pointerId);rebaseGesture()});viewport.addEventListener("pointermove",event=>{if(!drag||!pointers.has(event.pointerId))return;pointers.set(event.pointerId,pointerPosition(event));view=gestureView(panel,content,drag.view,drag.frame,gestureFrame([...pointers.values()]));fitted=view.scale<=fitView(panel,content).scale+1e-6;paint()});for(const event of["pointerup","pointercancel","lostpointercapture"])viewport.addEventListener(event,endPointer);viewport.addEventListener("keydown",event=>{if(!view||event.target!==viewport||event.ctrlKey||event.metaKey||event.altKey)return;if(event.key==="Home")fit();else if(event.key==="+"||event.key==="=")zoom(1.25);else if(event.key==="-"||event.key==="−")zoom(1/1.25);else{const directions={ArrowLeft:[40,0],ArrowRight:[-40,0],ArrowUp:[0,40],ArrowDown:[0,-40]};const direction=directions[event.key];if(!direction)return;clearGesture();view=constrainView(panel,content,{scale:view.scale,x:view.x+direction[0],y:view.y+direction[1]});paint()}event.preventDefault()});const observer=new ResizeObserver(refresh);observer.observe(viewport);refresh()}return{viewportSize,constrainView,fitView,gestureFrame,gestureView,zoomView,bind}})();if(typeof module!=="undefined"&&module.exports)module.exports=ExplainerDiagrams;if(typeof document!=="undefined")document.querySelectorAll("[data-diagram-viewport]").forEach(ExplainerDiagrams.bind);
